-- ZK Social PostgreSQL migration 0001 (PostgreSQL 16+)
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE account_status AS ENUM ('active','suspended','deleting');
CREATE TYPE post_visibility AS ENUM ('public','followers');
CREATE TYPE post_status AS ENUM ('published','hidden','deleted');
CREATE TYPE asset_status AS ENUM ('unverified','pending','confirmed','disputed');
CREATE TYPE transfer_status AS ENUM ('draft','prepared','awaiting_signature','signed','broadcast','confirming','confirmed','failed','reorged','cancelled');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),handle varchar(30) NOT NULL CHECK(handle ~ '^[a-z0-9_]{3,30}$'),display_name varchar(80) NOT NULL,bio varchar(500),avatar_key text,cover_key text,status account_status NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE UNIQUE INDEX users_handle_lower_unique ON users(lower(handle));
CREATE TABLE auth_identities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider text NOT NULL,provider_subject text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,provider_subject));
CREATE INDEX auth_identities_user_idx ON auth_identities(user_id);
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,refresh_hash text NOT NULL,token_family uuid NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE follows(follower_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,following_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(follower_id,following_id),CHECK(follower_id<>following_id));
CREATE INDEX follows_following_idx ON follows(following_id,created_at DESC);
CREATE TABLE blocks(blocker_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,blocked_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(blocker_id,blocked_id),CHECK(blocker_id<>blocked_id));
CREATE TABLE posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),author_id uuid NOT NULL REFERENCES users(id),parent_id uuid REFERENCES posts(id),quote_post_id uuid REFERENCES posts(id),body varchar(500) NOT NULL DEFAULT '',visibility post_visibility NOT NULL DEFAULT 'public',status post_status NOT NULL DEFAULT 'published',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX posts_author_cursor_idx ON posts(author_id,created_at DESC,id DESC);
CREATE INDEX posts_public_cursor_idx ON posts(created_at DESC,id DESC) WHERE visibility='public' AND status='published';
CREATE INDEX posts_parent_idx ON posts(parent_id,created_at);
CREATE TABLE media(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),object_key text NOT NULL UNIQUE,kind text NOT NULL CHECK(kind IN ('image','video')),mime_type text NOT NULL,byte_size bigint NOT NULL CHECK(byte_size>0),processing_state text NOT NULL DEFAULT 'pending' CHECK(processing_state IN ('pending','scanning','processing','ready','rejected','failed')),thumbnail_key text,playback_key text,alt_text text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE post_media(post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE,media_id uuid NOT NULL UNIQUE REFERENCES media(id),sort_order smallint NOT NULL CHECK(sort_order BETWEEN 0 AND 3),PRIMARY KEY(post_id,media_id),UNIQUE(post_id,sort_order));
CREATE TABLE reactions(user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('like')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,post_id,kind));
CREATE INDEX reactions_post_idx ON reactions(post_id);
CREATE TABLE bookmarks(user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,post_id));
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL DEFAULT 'direct' CHECK(kind IN ('direct')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversation_members(conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,joined_at timestamptz NOT NULL DEFAULT now(),last_read_at timestamptz,PRIMARY KEY(conversation_id,user_id));
CREATE INDEX conversation_members_user_idx ON conversation_members(user_id);
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_id uuid NOT NULL REFERENCES users(id),body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 4000),created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX messages_conversation_cursor_idx ON messages(conversation_id,created_at DESC,id DESC);
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recipient_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,actor_id uuid REFERENCES users(id) ON DELETE SET NULL,kind text NOT NULL,entity_id uuid,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_recipient_idx ON notifications(recipient_id,created_at DESC);
CREATE TABLE reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL REFERENCES users(id),target_kind text NOT NULL CHECK(target_kind IN ('user','post','message')),target_id uuid NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','reviewing','resolved','dismissed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX reports_queue_idx ON reports(status,created_at);
CREATE TABLE moderation_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid REFERENCES reports(id),moderator_id uuid NOT NULL REFERENCES users(id),target_kind text NOT NULL,target_id uuid NOT NULL,action text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,address text NOT NULL,nonce_hash text NOT NULL UNIQUE,domain text NOT NULL,network text NOT NULL CHECK(network='dogecoin-mainnet'),expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_connections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,address text NOT NULL,network text NOT NULL CHECK(network='dogecoin-mainnet'),provider text NOT NULL,verified_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX wallet_active_address_idx ON wallet_connections(network,address) WHERE revoked_at IS NULL;
CREATE INDEX wallet_user_idx ON wallet_connections(user_id);
CREATE TABLE drc20_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticker text NOT NULL,protocol_version text NOT NULL,deploy_txid text NOT NULL UNIQUE,decimals integer NOT NULL CHECK(decimals BETWEEN 0 AND 30),max_supply numeric(78,0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(ticker,protocol_version));
CREATE TABLE chain_blocks(height bigint NOT NULL,hash text PRIMARY KEY,parent_hash text,canonical boolean NOT NULL DEFAULT true,seen_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX chain_canonical_height_idx ON chain_blocks(height) WHERE canonical=true;
CREATE TABLE chain_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),txid text NOT NULL,event_index integer NOT NULL,block_hash text REFERENCES chain_blocks(hash),event_type text NOT NULL,payload jsonb NOT NULL,canonical boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(txid,event_index,block_hash));
CREATE INDEX chain_events_block_idx ON chain_events(block_hash);
CREATE TABLE asset_balances(wallet_id uuid NOT NULL REFERENCES wallet_connections(id) ON DELETE CASCADE,token_id uuid NOT NULL REFERENCES drc20_tokens(id),amount_base_units numeric(78,0) NOT NULL CHECK(amount_base_units>=0),indexed_block_hash text REFERENCES chain_blocks(hash),indexed_height bigint,status asset_status NOT NULL DEFAULT 'unverified',updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(wallet_id,token_id));
CREATE TABLE transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),wallet_id uuid NOT NULL REFERENCES wallet_connections(id),token_id uuid NOT NULL REFERENCES drc20_tokens(id),recipient_address text NOT NULL,amount_base_units numeric(78,0) NOT NULL CHECK(amount_base_units>0),status transfer_status NOT NULL DEFAULT 'draft',idempotency_key text NOT NULL,provider text,prepare_payload jsonb,prepare_expires_at timestamptz,error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key));
CREATE INDEX transfers_user_idx ON transfers(user_id,created_at DESC);
CREATE TABLE transfer_steps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transfer_id uuid NOT NULL REFERENCES transfers(id) ON DELETE CASCADE,step_index integer NOT NULL,kind text NOT NULL CHECK(kind IN ('inscription','transfer','other')),unsigned_payload_hash text,signed_payload_hash text,txid text,block_hash text,confirmations integer NOT NULL DEFAULT 0,status transfer_status NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(transfer_id,step_index));
CREATE UNIQUE INDEX transfer_steps_txid_idx ON transfer_steps(txid) WHERE txid IS NOT NULL;
CREATE TABLE outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),aggregate_kind text NOT NULL,aggregate_id uuid NOT NULL,event_kind text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz);
CREATE INDEX outbox_pending_idx ON outbox_events(created_at) WHERE processed_at IS NULL;
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES users(id),action text NOT NULL,subject_kind text NOT NULL,subject_id text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
